// Cloudflare Workers entry (wrangler.jsonc "main"). Wraps the worker generated by
// `opennextjs-cloudflare build` and adds a `scheduled` handler so the Cron Trigger
// in wrangler.jsonc runs the same hourly check Vercel runs via vercel.json (split
// into per-minute slices, see lib/guard/cron.ts).
// https://opennext.js.org/cloudflare/howtos/custom-worker
//
// Not used by `next build` / Vercel. Types are declared locally so `tsc` passes
// before .open-next/ exists and without pulling the Workers runtime types into the app.

// Must stay first: globals the OpenNext bundles need at startup, and NODE_ENV (see the file).
import "./cf-prelude";
// @ts-ignore `.open-next/worker.js` is generated at build time
import { default as handler } from "./.open-next/worker.js";
// @ts-ignore generated at build time. Evaluate the Next.js server at isolate startup
// (1 s startup budget) instead of inside the first dynamic request (10 ms CPU budget).
import "./.open-next/server-functions/default/handler.mjs";
// The cron slice runs without Next.js (bundled separately by wrangler; evaluated at startup).
import { cronBatchSize, runCronSlice } from "./lib/guard/cron";
import { getKV } from "./lib/redis";
import { runStartupChecks } from "./lib/startup-checks";
// @ts-ignore generated after the build (scripts/security-headers.mjs cf): per-page CSP + common headers
import policies from "./.open-next/security-headers.json";
import { cspForPath } from "./lib/security-headers.mjs";

type Env = Record<string, unknown>;
type Ctx = { waitUntil(p: Promise<unknown>): void; passThroughOnException(): void };
type OpenNextHandler = { fetch(request: Request, env: Env, ctx: Ctx): Promise<Response> };
type ScheduledController = { cron: string; scheduledTime: number };

let startupChecked: string | null | undefined;
/** runStartupChecks once per isolate (after the env is copied in); the problem, or null. */
function startupProblem(): string | null {
  if (startupChecked === undefined) {
    try {
      // A deployed Worker is always production (Atlas re-check #3): NODE_ENV=development/test would turn
      // off every secret check, so a vars/secret that sets it to anything else is a configuration error.
      // Read through a variable: wrangler replaces the literal `process.env.NODE_ENV` at bundle time
      // ("development" under `wrangler dev`), which is not the runtime value the checks use.
      const runtimeNodeEnv = (process.env as Record<string, string | undefined>)["NODE_" + "ENV"];
      if (runtimeNodeEnv !== "production") throw new Error(`NODE_ENV must be "production" on Workers (got "${runtimeNodeEnv}"); remove the NODE_ENV var/secret`);
      runStartupChecks(process.env);
      startupChecked = null;
    } catch (err) {
      startupChecked = err instanceof Error ? err.message : String(err);
    }
  }
  return startupChecked;
}

/**
 * Cron: one small slice of the hourly check per run (lib/guard/cron.ts), called
 * directly — not through the Next.js route — so a run costs only the check itself
 * (no Next request handling, ~4–5 ms), even in a fresh isolate. With the
 * `* * * * *` trigger and CRON_BATCH_SIZE (wrangler.jsonc) that is up to 60 runs an hour.
 * Failures are thrown so they show as failed invocations in the Cron Events log.
 */
async function runCron(controller: ScheduledController, env: Env): Promise<void> {
  // process.env carries vars/secrets (nodejs_compat); prefer the binding values explicitly.
  for (const [k, v] of Object.entries(env)) if (typeof v === "string") process.env[k] = v;
  // The startup checks (instrumentation.ts) guard the Next.js server; the cron runs without it.
  // A broken setup must not stop the monitoring, so check, do the work anyway, then fail the
  // invocation so it shows in the Cron Events log.
  const configError = startupProblem();
  const result = await runCronSlice(getKV(), { now: new Date(controller.scheduledTime), batch: cronBatchSize() });
  const line = `[cron] ${controller.cron} ${JSON.stringify(result)}`;
  if (configError) throw new Error(`${line} — configuration error: ${configError}`);
  // Undecryptable tokens (R1-01) also fail the invocation, so they show in the Cron Events log.
  if (result.errors || result.tokenErrors) throw new Error(line);
  console.log(line);
}

/**
 * Rate limits key on the client IP (lib/ratelimit.ts reads x-forwarded-for). On
 * Cloudflare the client can prepend its own x-forwarded-for entries, but
 * cf-connecting-ip is always set by Cloudflare, so pin x-forwarded-for to it.
 */
function withClientIp(request: Request): Request {
  const ip = request.headers.get("cf-connecting-ip");
  if (!ip) return request;
  const headers = new Headers(request.headers);
  headers.set("x-forwarded-for", ip);
  headers.set("x-real-ip", ip);
  return new Request(request, { headers });
}

/**
 * Every request: the startup checks must have passed in this isolate (lib/startup-checks.ts). The
 * instrumentation hook already makes Next answer 500 when they fail; this is the same check at the
 * Worker's edge, so a misconfigured deployment is refused even if the hook doesn't load (as before
 * cf-prelude.ts) — including static pages. Once per isolate; afterwards a cached boolean.
 */
function refuseIfMisconfigured(env: Env): Response | null {
  if (startupChecked === undefined) for (const [k, v] of Object.entries(env)) if (typeof v === "string") process.env[k] = v;
  const problem = startupProblem();
  if (!problem) return null;
  console.error(`[startup] ${problem}`);
  return new Response("Server misconfigured. The operator has been notified in the logs.", { status: 500, headers: { "content-type": "text/plain; charset=utf-8", "cache-control": "no-store" } });
}

type Policies = { routes: Record<string, string>; fallback: string; nonHtml: string; common: Record<string, string> };

/**
 * Security headers on every Worker response — pages served from the cache included (lib/security-headers.mjs).
 * HTML gets its page's CSP (hashes of that page's inline scripts), anything else the "load nothing" CSP.
 * Files the assets binding serves directly get theirs from .open-next/assets/_headers.
 */
let missWarned = false;
function withSecurityHeaders(request: Request, res: Response): Response {
  const out = new Response(res.body, res);
  const p = policies as Policies;
  for (const [k, v] of Object.entries(p.common)) out.headers.set(k, v);
  const html = (out.headers.get("content-type") ?? "").includes("text/html");
  // The hashes come from the prerendered HTML. A page rendered at runtime instead (cache miss — e.g.
  // the static-assets cache wasn't populated: deploy with `npm run deploy`, preview with
  // `npm run preview`) can carry different inline scripts, which this CSP would block. Say so.
  if (html && out.headers.get("x-nextjs-cache") === "MISS" && !missWarned) {
    missWarned = true;
    console.error("[csp] a page was rendered at runtime (cache MISS): its inline scripts may not match the build-time CSP hashes. Populate the cache (opennextjs-cloudflare deploy / preview / populateCache).");
  }
  out.headers.set("Content-Security-Policy", html ? cspForPath(p, new URL(request.url).pathname) : p.nonHtml);
  out.headers.delete("X-Security-Headers");
  return out;
}

export default {
  fetch: async (request: Request, env: Env, ctx: Ctx) =>
    withSecurityHeaders(request, refuseIfMisconfigured(env) ?? (await (handler as OpenNextHandler).fetch(withClientIp(request), env, ctx))),
  async scheduled(controller: ScheduledController, env: Env) {
    await runCron(controller, env);
  },
};
